namespace PaymentAuthorization.ArchitectureTest;

/// <summary>
/// Guards the layering of the solution: business logic (Domain, Application) must never
/// reach into technical/infrastructure details. These checks run against the compiled
/// assemblies, so any violation is caught at build time instead of in code review.
/// </summary>
public sealed class LayerDependencyTests
{
    private const string DomainAssembly = "PaymentAuthorization.Domain";
    private const string ApplicationAssembly = "PaymentAuthorization.Application";
    private const string InfrastructureAssembly = "PaymentAuthorization.Infrastructure";

    [Fact]
    public void Domain_does_not_depend_on_application_or_infrastructure()
    {
        var result = Types.InAssembly(typeof(Domain.Money).Assembly)
            .Should()
            .NotHaveDependencyOnAny(ApplicationAssembly, InfrastructureAssembly)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(typeof(Application.AuthorizePayment).Assembly)
            .Should()
            .NotHaveDependencyOn(InfrastructureAssembly)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    private static string Describe(TestResult result) =>
        "Layer violation found in: " + string.Join(", ", result.FailingTypeNames ?? []);
}
EOF
